	@Test
	void wildcardBatchPhysicalReopensKeepBagsAndReportOptionalRows(@TempDir File directory) throws Exception {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		String previousBatch = System.getProperty(NativeBatch.ENABLED_PROPERTY);
		String previousWildcard = System.getProperty(LmdbWildcardPredicateBatch.ENABLED_PROPERTY);
		var manager = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyBuildOnStart(false));
		SailRepository repository = new SailRepository(store);
		try {
			LmdbNativeHashJoin.queryMemoryOverride = manager;
			System.setProperty(NativeBatch.ENABLED_PROPERTY, "true");
			System.setProperty(LmdbWildcardPredicateBatch.ENABLED_PROPERTY, "true");
			var factory = SimpleValueFactory.getInstance();
			var subject = factory.createIRI("urn:wildcard-bypass:s");
			var predicate = factory.createIRI("urn:wildcard-bypass:p");
			var value = factory.createLiteral("payload");
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(subject, predicate, value);
				connection.commit();
			}
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				SyntheticValueSource source = SyntheticValueSource.forEvaluation((NativeLmdbQuerySource) dataset);
				source.executionContext().initializeQueryBase(EmptyBindingSet.getInstance());
				NativeSlotLayout layout = new NativeSlotLayout(Map.of("s", 0, "p", 1, "value", 2), null);
				layout.freeze(List.of("s", "p", "value"));
				QueryRoot target = new QueryRoot(new SingletonSet());
				target.setRuntimeTelemetryEnabled(true);
				RowState row = new RowState(source, layout, EmptyBindingSet.getInstance(), target);
				try {
					NativeRowSeeder.seed(row.slots, layout, row.base, source);
					row.recomputeBoundMask();
					long subjectId = source.idOf(subject);
					SlotPlan left = SlotPlan.values(new ValuesRow[] {
							new ValuesRow(new int[] { 0 }, new long[] { subjectId }),
							new ValuesRow(new int[] { 0 }, new long[] { subjectId }) });
					PatternPlan right = new PatternPlan(Term.slot(0), Term.slot(1), Term.slot(2), Term.unbound(),
							ContextConstraint.UNRESTRICTED, false, 1D);
					LeftJoinPlan optional = new LeftJoinPlan(left, right);
					for (int physical = 0; physical < 2; physical++) {
						long before = LmdbWildcardPredicateBatch.OPTIONAL_BATCHES.get();
						List<String> rows = new ArrayList<>();
						try (BatchCursor cursor = optional.openBatch(row, 8)) {
							assertThat(cursor).isNotNull();
							NativeBatch batch = new NativeBatch(3, 8);
							int count;
							while ((count = cursor.fill(batch)) != 0) {
								for (int i = 0; i < count; i++) {
									int selected = batch.selection[i];
									long weight = cursor instanceof WeightedBatchCursor weighted
											? weighted.weight(selected)
											: 1L;
									for (long copy = 0; copy < weight; copy++) {
										rows.add(source.lazyValue(batch.get(2, selected)).stringValue());
									}
								}
							}
						}
						assertThat(rows).containsExactly("payload", "payload");
						assertThat(LmdbWildcardPredicateBatch.OPTIONAL_BATCHES.get()).isGreaterThan(before);
					}
					assertThat(target.getLongMetricActual("nativeOptionalOutputRows")).isEqualTo(4L);
					assertThat(target.getLongMetricActual("nativeOptionalBuilds")).isGreaterThanOrEqualTo(0L);
				} finally {
					row.closeDecodedInputs();
					source.executionContext().close();
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				LmdbNativeHashJoin.queryMemoryOverride = previous;
				restore(NativeBatch.ENABLED_PROPERTY, previousBatch);
				restore(LmdbWildcardPredicateBatch.ENABLED_PROPERTY, previousWildcard);
			}
		}
		assertThat(manager.usedBytes()).isZero();
	}

	private static void restore(String key, String value) {
		if (value == null) {
			System.clearProperty(key);
		} else {
			System.setProperty(key, value);
		}
	}
